<?php
declare(strict_types=1);namespace Atlas\Platform\PatientResources\Repositories;use Atlas\Platform\PatientResources\Domain\PatientResourceVariant;use RuntimeException;final class WordPressVariantRepository implements VariantRepository{private string $table;public function __construct(private object $db){$this->table=$db->prefix.'atlas_patient_resource_variants';}public function save(string $org,string $version,array $custom,string $key,int $actor):PatientResourceVariant{$existing=$this->byKey($key);if($existing!==null){if($existing->organizationId!==$org||$existing->resourceVersionId!==$version){throw new RuntimeException('Idempotency key conflict.');}return $existing->replayed();}$id=wp_generate_uuid4();$created=gmdate('Y-m-d H:i:s');$json=wp_json_encode($custom);if(!is_string($json)||$this->db->insert($this->table,['id'=>$id,'organization_id'=>$org,'resource_version_id'=>$version,'customizations_json'=>$json,'idempotency_key'=>$key,'created_by'=>$actor,'created_at'=>$created],['%s','%s','%s','%s','%s','%d','%s'])===false){$existing=$this->byKey($key);if($existing!==null){return $existing->replayed();}throw new RuntimeException('Unable to save patient resource variant.');}return new PatientResourceVariant($id,$org,$version,$custom,$created);}public function findForOrganization(string $id,string $org):?PatientResourceVariant{$r=$this->db->get_row($this->db->prepare("SELECT * FROM `{$this->table}` WHERE id=%s AND organization_id=%s LIMIT 1",$id,$org),ARRAY_A);return $this->map($r);}private function byKey(string $key):?PatientResourceVariant{$r=$this->db->get_row($this->db->prepare("SELECT * FROM `{$this->table}` WHERE idempotency_key=%s LIMIT 1",$key),ARRAY_A);return $this->map($r);}private function map(mixed $r):?PatientResourceVariant{if(!is_array($r)){return null;}$data=json_decode((string)$r['customizations_json'],true);return is_array($data)?new PatientResourceVariant((string)$r['id'],(string)$r['organization_id'],(string)$r['resource_version_id'],array_map('strval',$data),(string)$r['created_at']):null;}}
